import {BOOK} from './book-content.js?v=5.0.1';
import {CHAT_COPY} from './shared/conversation-copy.js?v=5.0.1';
import {UI} from './shared/copy.js?v=5.0.1';
import {esc,getLang,setLang,languageOptions,icon} from './shared/core.js?v=5.0.1';
let lang=getLang(),menuOpen=false;const root=document.querySelector('#book');
const b=()=>BOOK[lang],t=k=>CHAT_COPY[lang]?.[k]||UI[lang][k]||k;
function render(){document.documentElement.lang=lang;document.title='one ai · 원샵 | '+b().contents+' 5.0';root.innerHTML=`<div class="reading-progress" id="progress"></div><header class="book-top"><button id="nav-toggle" class="icon-button" aria-label="${esc(b().contents)}" aria-expanded="${menuOpen}">${icon('menu')}</button><a class="platform" href="#cover"><img src="assets/mark.svg" width="34" height="34" alt=""><b>one ai<span>원샵</span></b></a><span class="version">5.0</span><div class="book-tools"><select id="book-language" aria-label="${esc(t('language'))}">${languageOptions(lang)}</select><a class="top-guest" href="jumo/?lang=${lang}">${esc(b().guest)} ↗</a><button class="icon-button" id="print-book" aria-label="${esc(b().print)}">${icon('orders')}</button></div></header><button id="nav-overlay" aria-label="${esc(t('close'))}" ${menuOpen?'':'hidden'}></button><aside class="book-nav ${menuOpen?'open':''}" id="book-nav"><p>${esc(b().contents)}</p><a href="#cover" class="active" data-chapter="cover"><span>00</span>${esc(b().title)}</a>${b().sections.map((s,i)=>`<a href="#${s.id}" data-chapter="${s.id}"><span>${String(i+1).padStart(2,'0')}</span>${esc(s.title)}</a>`).join('')}<div class="nav-foot">${esc(b().partner)}<br>2026.10.27 · 5.0</div></aside><main id="main"><section id="cover" class="cover chapter"><div class="cover-partner">${esc(b().partner)}<span>2026 · 5.0</span></div><h1>${esc(b().subtitle)}</h1><p class="cover-intro">${esc(b().intro)}</p><div class="cover-actions"><a class="button primary" href="jumo/?lang=${lang}">${esc(b().guest)}${icon('arrow')}</a><a class="button secondary" href="jumo/owner.html?lang=${lang}">${esc(b().owner)}</a><a class="text-link" href="#glance">${esc(b().read)} ↓</a></div><div class="cover-picture"><img src="jumo/assets/exterior.jpg" alt="one ai · 원샵" width="1536" height="1024"><div class="picture-caption"><b>one ai</b><span>원샵</span></div></div><div class="cover-note">${esc(b().demoNote)}</div><p class="translation-note">${esc(b().translationNote)}</p></section>${b().sections.map(section).join('')}<footer><a class="platform" href="#cover"><img src="assets/mark.svg" width="38" height="38" alt=""><b>one ai<span>원샵</span></b></a><h2>${esc(b().subtitle)}</h2><p>${esc(b().partner)}</p><a href="jumo/?lang=${lang}" class="button primary">${esc(b().guest)}${icon('arrow')}</a></footer></main>`;bind();updateProgress();}
function section(s,i){return `<section class="book-chapter chapter" id="${s.id}"><div class="chapter-head"><span class="chapter-number">${String(i+1).padStart(2,'0')}</span><p>${esc(s.title)}</p></div><div class="chapter-layout"><h2>${esc(s.lead)}</h2><div class="chapter-copy">${s.paragraphs.map(p=>`<p>${esc(p)}</p>`).join('')}</div></div><ul class="principle-row">${s.points.map(x=>`<li>${icon('check')}<span>${esc(x)}</span></li>`).join('')}</ul>${extra(s.id)}</section>`}
function extra(id){if(id==='experience')return `<div class="jumo-feature"><img class="jumo-food" src="jumo/assets/jeon.jpg" alt="주모 Jumo"><div class="jumo-feature-copy"><img class="jumo-mark" src="jumo/assets/brand.png" alt="주모 Jumo"><h3>주모 <span>Jumo</span></h3><p>${esc(t('flowGuest'))}</p><a href="jumo/?lang=${lang}" class="button warm">${esc(b().guest)}${icon('arrow')}</a><small>${esc(b().demoNote)}</small></div></div><div class="live-demo-panel"><div><span class="live-label">one ai · Jumo demo</span><h3>${esc(t('flowAbout'))}</h3><p>${esc(t('flowCaption'))}</p><div class="cover-actions"><a class="button primary" href="jumo/?lang=${lang}">${esc(b().guest)}${icon('arrow')}</a><a class="button secondary" href="jumo/owner.html?lang=${lang}#storeSetup">${esc(b().owner)}</a></div><p class="translation-note">${esc(t('scenario'))}</p></div><div class="book-phone"><iframe src="jumo/?lang=${lang}&preview=1" title="${esc(b().guest)}" loading="lazy"></iframe></div></div>`;
 if(id==='onboarding')return `<a class="owner-feature" href="jumo/owner.html?lang=${lang}#storeSetup"><div>${icon('profile')}<h3>${esc(t('storeSetup'))}</h3><p>${esc(t('storeName'))} · ${esc(t('upload'))} · QR</p></div><span class="round-arrow">${icon('arrow')}</span></a>`;
 if(id==='team')return `<div class="team-demo"><a href="jumo/?lang=${lang}#games">${icon('games')}<strong>${esc(t('games'))}</strong><span>${esc(t('gameNote'))}</span></a><a href="jumo/owner.html?lang=${lang}#dashboard">${icon('chat')}<strong>${esc(t('guestLog'))}</strong><span>${esc(t('memberNotice'))}</span></a></div>`;
 if(id==='architecture')return `<div class="architecture-diagram"><div>${esc(t('menu'))} / ${esc(t('chat'))}</div><span>↓</span><div class="architecture-center">one ai · 원샵<br><small>${esc(t('scopeNote'))} · ${esc(t('budgetTitle'))}</small></div><span>↓</span><div class="architecture-end"><b>${esc(t('storeAssistant'))}</b><b>POS</b><b>${esc(t('orderInbox'))}</b></div><p>${esc(t('notConnected'))} · ${esc(b().demoNote)}</p></div>`;
 if(id==='operations')return `<div class="steps">${['pending','accepted','preparing','ready','completed'].map(k=>`<span>${esc(t(k))}</span>`).join('<i>→</i>')}</div><a class="text-link" href="jumo/owner.html?lang=${lang}#orderInbox">${esc(t('orderInbox'))} ↗</a>`;
 if(id==='business')return `<div class="subscription-note"><strong>${esc(t('subscription'))}</strong><p>${esc(t('subscriptionNote'))}</p><a href="jumo/owner.html?lang=${lang}#dashboard" class="text-link">${esc(t('dashboard'))} ↗</a></div>`;
 if(id==='qr')return `<a class="button secondary" href="jumo/owner.html?lang=${lang}#storeSetup">${icon('qr')}${esc(t('qrTitle'))}</a>`;
 if(id==='faq')return `<div class="sources"><h3>${esc(b().sourceTitle)}</h3><a href="https://isaacweb007.github.io/jumo-joseon-hiphop-book/?lang=ko#cover" target="_blank" rel="noopener">주모 · Jumo — brand & menu reference ↗</a><a href="https://familywallet-book.vercel.app/#cover" target="_blank" rel="noopener">FamilyWallet — project book reference ↗</a><a href="https://developers.openai.com/api/reference/responses/overview" target="_blank" rel="noopener">OpenAI Responses API ↗</a><a href="api/pos-contract.json" target="_blank" rel="noopener">${esc(t('apiContract'))} ↗</a></div>`;
 return '';}
function setMenu(open){menuOpen=open;document.querySelector('#book-nav').classList.toggle('open',open);document.querySelector('#nav-overlay').hidden=!open;document.querySelector('#nav-toggle').setAttribute('aria-expanded',String(open));}
function bind(){document.querySelector('#book-language').addEventListener('change',e=>{lang=e.target.value;setLang(lang);render()});document.querySelector('#nav-toggle').addEventListener('click',()=>setMenu(!menuOpen));document.querySelector('#nav-overlay').addEventListener('click',()=>setMenu(false));document.querySelector('#print-book').addEventListener('click',()=>window.print());document.querySelector('#book-nav').addEventListener('click',e=>{if(e.target.closest('a'))setMenu(false)});}
let scheduled=false;function updateProgress(){const total=document.documentElement.scrollHeight-innerHeight;document.querySelector('#progress').style.width=(total?scrollY/total*100:0)+'%';let active='cover';document.querySelectorAll('.chapter').forEach(x=>{if(x.getBoundingClientRect().top<220)active=x.id});document.querySelectorAll('[data-chapter]').forEach(x=>{x.classList.toggle('active',x.dataset.chapter===active);if(x.dataset.chapter===active)x.setAttribute('aria-current','location');else x.removeAttribute('aria-current')});scheduled=false;}
addEventListener('scroll',()=>{if(!scheduled){scheduled=true;requestAnimationFrame(updateProgress)}},{passive:true});addEventListener('keydown',e=>{if(e.key==='Escape')setMenu(false)});render();
